package solution

import (
	"errors"
	"reflect"
	"testing"
)

func TestCatalogPutGetReplaceAndExactKeys(t *testing.T) {
	c := NewCatalog()
	first := Artifact{Workspace: "ws", Namespace: "ns", Alias: "a", URI: "u1", Digest: "d1"}
	if err := c.Put(first); err != nil { t.Fatalf("Put: %v", err) }
	if got, err := c.Get(Lookup{Workspace: "ws", Namespace: "ns", Alias: "a"}); err != nil || got != first {
		t.Fatalf("tuple Get = %#v, %v", got, err)
	}
	if got, err := c.Get(Lookup{URI: "u1"}); err != nil || got != first {
		t.Fatalf("URI Get = %#v, %v", got, err)
	}
	replacement := Artifact{Workspace: "ws", Namespace: "ns", Alias: "a", Digest: "d2"}
	if err := c.Put(replacement); err != nil { t.Fatalf("replacement Put: %v", err) }
	if c.Count() != 1 { t.Fatalf("Count = %d, want 1", c.Count()) }
	if got, err := c.Get(Lookup{Workspace: "ws", Namespace: "ns", Alias: "a"}); err != nil || got != replacement {
		t.Fatalf("replaced Get = %#v, %v", got, err)
	}
	if _, err := c.Get(Lookup{URI: "u1"}); !errors.Is(err, ErrNotFound) { t.Fatalf("old URI error = %v", err) }
	if _, err := c.Get(Lookup{Workspace: "WS", Namespace: "ns", Alias: "a"}); !errors.Is(err, ErrNotFound) {
		t.Fatalf("case-sensitive Get error = %v", err)
	}
}

func TestCatalogValidationAndAmbiguousURI(t *testing.T) {
	c := NewCatalog()
	invalid := []Artifact{
		{},
		{Namespace: "n", Alias: "a", URI: "u"},
		{Workspace: "w", Alias: "a", URI: "u"},
		{Workspace: "w", Namespace: "n", URI: "u"},
		{Workspace: "w", Namespace: "n", Alias: "a"},
	}
	for _, a := range invalid {
		if err := c.Put(a); !errors.Is(err, ErrInvalidArtifact) { t.Errorf("Put(%#v) error = %v", a, err) }
	}
	if c.Count() != 0 { t.Fatalf("invalid puts changed count to %d", c.Count()) }
	for _, a := range []Artifact{
		{Workspace: "w", Namespace: "n", Alias: "a", URI: "same"},
		{Workspace: "w", Namespace: "n", Alias: "b", URI: "same", Digest: "d"},
	} {
		if err := c.Put(a); err != nil { t.Fatal(err) }
	}
	if _, err := c.Get(Lookup{URI: "same"}); !errors.Is(err, ErrNotFound) { t.Fatalf("ambiguous URI error = %v", err) }
	invalidLookups := []Lookup{
		{},
		{URI: "u", Workspace: "w"},
		{Workspace: "w"},
		{Workspace: "w", Namespace: "n"},
		{Namespace: "n", Alias: "a"},
	}
	for _, q := range invalidLookups {
		if _, err := c.Get(q); !errors.Is(err, ErrInvalidLookup) { t.Errorf("Get(%#v) error = %v", q, err) }
	}
}

func TestCatalogListDeleteAndNilReceiver(t *testing.T) {
	c := NewCatalog()
	items := []Artifact{
		{Workspace: "b", Namespace: "a", Alias: "a", Digest: "1"},
		{Workspace: "a", Namespace: "b", Alias: "a", Digest: "2"},
		{Workspace: "a", Namespace: "a", Alias: "b", Digest: "3"},
		{Workspace: "a", Namespace: "a", Alias: "a", Digest: "4"},
	}
	for _, a := range items { if err := c.Put(a); err != nil { t.Fatal(err) } }
	want := []Artifact{items[3], items[2], items[1], items[0]}
	got, err := c.List(0, 20)
	if err != nil || !reflect.DeepEqual(got, want) { t.Fatalf("List = %#v, %v; want %#v", got, err, want) }
	page, err := c.List(1, 2)
	if err != nil || !reflect.DeepEqual(page, want[1:3]) { t.Fatalf("page = %#v, %v", page, err) }
	page[0].Digest = "changed"
	again, _ := c.Get(Lookup{Workspace: "a", Namespace: "a", Alias: "b"})
	if again.Digest != "3" { t.Fatal("returned list exposed catalog storage") }
	for _, tc := range []struct{ offset, limit int }{{0, 0}, {4, 1}, {100, 3}} {
		x, e := c.List(tc.offset, tc.limit)
		if e != nil || x == nil || len(x) != 0 { t.Errorf("List(%d,%d) = %#v, %v", tc.offset, tc.limit, x, e) }
	}
	if _, err := c.List(-1, 1); err == nil { t.Error("negative offset accepted") }
	if _, err := c.List(0, -1); err == nil { t.Error("negative limit accepted") }
	if err := c.Delete("a", "a", "a"); err != nil { t.Fatalf("Delete: %v", err) }
	if err := c.Delete("a", "a", "a"); !errors.Is(err, ErrNotFound) { t.Fatalf("second Delete = %v", err) }
	if err := c.Delete("", "a", "a"); err == nil { t.Error("incomplete Delete accepted") }

	var nilCatalog *Catalog
	if nilCatalog.Count() != 0 { t.Fatal("nil Count was not zero") }
	if err := nilCatalog.Put(Artifact{Workspace: "w", Namespace: "n", Alias: "a", URI: "u"}); !errors.Is(err, ErrInvalidArtifact) { t.Fatalf("nil Put = %v", err) }
	if _, err := nilCatalog.Get(Lookup{URI: "u"}); !errors.Is(err, ErrNotFound) { t.Fatalf("nil Get = %v", err) }
	if err := nilCatalog.Delete("w", "n", "a"); !errors.Is(err, ErrNotFound) { t.Fatalf("nil Delete = %v", err) }
	x, err := nilCatalog.List(0, 1)
	if err != nil || x == nil || len(x) != 0 { t.Fatalf("nil List = %#v, %v", x, err) }
}

package solution

import "testing"

func TestReviewCatalogBoundaries0121(t *testing.T) {
	t.Run("tuple identity", func(t *testing.T) {
		c := NewCatalog()
		for _, a := range []Artifact{
			{Workspace:"a", Namespace:"b\x00c", Alias:"d", URI:"one"},
			{Workspace:"a\x00b", Namespace:"c", Alias:"d", URI:"two"},
		} { if err := c.Put(a); err != nil { t.Fatal(err) } }
		if c.Count() != 2 { t.Fatalf("distinct tuples collided: count=%d", c.Count()) }
	})
	t.Run("pagination overflow", func(t *testing.T) {
		c := NewCatalog()
		for _, key := range []string{"a","b"} {
			if err := c.Put(Artifact{Workspace:key,Namespace:"n",Alias:"x",URI:key}); err != nil { t.Fatal(err) }
		}
		defer func() { if p := recover(); p != nil { t.Errorf("valid pagination panicked: %v", p) } }()
		items, err := c.List(1, int(^uint(0)>>1))
		if err != nil || len(items) != 1 { t.Fatalf("items=%v err=%v", items, err) }
	})
}

