	if c.items == nil {
		c.items = make(map[string]Artifact)
	}
	c.items[artifactKey(a.Workspace, a.Namespace, a.Alias)] = a
	return nil
}

func (c *Catalog) Get(q Lookup) (Artifact, error) {
	uriForm := q.URI != "" && q.Workspace == "" && q.Namespace == "" && q.Alias == ""
	tupleForm := q.URI == "" && q.Workspace != "" && q.Namespace != "" && q.Alias != ""
	if !uriForm && !tupleForm {
		return Artifact{}, ErrInvalidLookup
	}
	if c == nil {
		return Artifact{}, ErrNotFound
	}
	if tupleForm {
		a, ok := c.items[artifactKey(q.Workspace, q.Namespace, q.Alias)]
		if !ok {
			return Artifact{}, ErrNotFound
		}
		return a, nil
	}
	var found Artifact
	matches := 0
	for _, a := range c.items {
		if a.URI == q.URI {
			found = a
			matches++
		}
	}
	if matches != 1 {
		return Artifact{}, ErrNotFound
	}
	return found, nil
}

func (c *Catalog) Delete(workspace, namespace, alias string) error {
	if workspace == "" || namespace == "" || alias == "" {
		return ErrInvalidLookup
	}
	if c == nil {
		return ErrNotFound
	}
	key := artifactKey(workspace, namespace, alias)
	if _, ok := c.items[key]; !ok {
		return ErrNotFound
	}
	delete(c.items, key)
	return nil
}

func (c *Catalog) List(offset, limit int) ([]Artifact, error) {
	if offset < 0 || limit < 0 {
		return nil, ErrInvalidLookup
	}
	all := make([]Artifact, 0)
	if c != nil {
		all = make([]Artifact, 0, len(c.items))
		for _, a := range c.items {
			all = append(all, a)
		}
	}
	sort.Slice(all, func(i, j int) bool {
		if all[i].Workspace != all[j].Workspace {
			return all[i].Workspace < all[j].Workspace
		}
		if all[i].Namespace != all[j].Namespace {
			return all[i].Namespace < all[j].Namespace
		}
		return all[i].Alias < all[j].Alias
	})
	if limit == 0 || offset >= len(all) {
		return []Artifact{}, nil
	}
	end := offset + limit
	if end > len(all) {
		end = len(all)
	}
	return append([]Artifact(nil), all[offset:end]...), nil
}

func (c *Catalog) Count() int {
	if c == nil {
		return 0
	}
	return len(c.items)
}
